   changed=copy.deepcopy(d['state']);changed['profiles'][0][key]=value;hidden=viewed(changed);check('changed '+key+' hides historical provider evidence','Question unavailable'in json.dumps(hidden['ui'].get('modal'))and'Reported source'not in json.dumps(hidden['ui'].get('modal')))
