  changed=copy.deepcopy(d['state']);changed['agents'][0]['tools']='read,hypotheses';model=event(changed,'send',{'draft':'The old source needs current permission.'});model=model_process(model,{'action':'current','id':qid,'section':'evidence'});feedback=json.loads(model['effect']['wire'].split('\r\n\r\n',1)[1])['messages'][-1]if model['effect']else{};check('model permission revocation returns an error without historical source disclosure','Question unavailable'in json.dumps(feedback)and'Reported source'not in json.dumps(feedback)and'completed_result'in json.dumps(feedback)and not model['state'].get('pending'));model=event(model['state'],'cancel')
  intrinsic=event(state('read,web_search'),'send',{'draft':'Investigate with no journal tool or selected skill.'});check('intrinsic method needs no journal tool invocation','Investigation is intrinsic'in intrinsic['effect']['wire']and'process:{action'not in intrinsic['effect']['wire']);intrinsic=reply(intrinsic,search());check('automatic source capture needs no journal tool permission',len(current(intrinsic)['evidence'])==1 and not intrinsic['state']['busy'])
  standalone=event(state(),'delegate',{'task':'Investigate as an ordinary assigned task.'});standalone=reply(standalone,search());check('standalone task also captures its actual provider source',len(current(standalone)['evidence'])==1 and not standalone['state'].get('delegation_stack')and not standalone['state']['busy'])
  child_state=state();child_profile=copy.deepcopy(child_state['profiles'][0]);child_profile.update(name='Child connection',endpoint='http://child.test/v1/messages');child_state['profiles'].append(child_profile);child_state['agents']=[dict(name='Parent',model='0',tools='hypotheses,delegate,web_search',subagents=[1]),dict(name='Child',model='1',tools='read,web_search',subagents=[])]
  child=event(child_state,'send',{'draft':'Have the actual child investigate the reported source.'});parent_id=current(child)['id'];child=reply(child,[dict(type='text',text=json.dumps(dict(tool='delegate',args={'agent':1,'task':'Inspect provider-reported sources.'})))]);child=event(child['state'],'approve');check('reviewed child retains intrinsic method and its actual owner',child['state']['request_index']==1 and'Investigation is intrinsic'in child['effect']['wire']and child['effect'].get('model_ticket')==child['state']['model_expected']);child_id=current(child)['id'];child=reply(child,search('child'));child_case=next(c for c in child['state']['inquiry_records']['items']if c['id']==child_id)
  check('actual child return retains evidence in its own linked question',child_case['parent']==parent_id and len(child_case['evidence'])==1 and json.loads(child_case['evidence'][0]['output'])['reports'][0]['call_id']=='search_child')
  check('owned child source response resumes the captured parent',child['state']['request_index']==0 and not child['state'].get('delegation_stack')and'Answer using the reported metadata.'in child['effect']['wire']);child=reply(child,[dict(type='text',text='Parent answer from actual child work.')]);assert not child['state']['busy']
  pending=event(state(),'send',{'draft':'A provider query pauses before results.'});call=[dict(type='server_tool_use',id='search_later',name='web_search',input={'query':'continuation query'})];pending=reply(pending,call,'pause_turn');check('query-only paused response does not invent completed evidence',current(pending)['evidence']==[]and pending['state']['dialog']=='hosted_pause')
