  oversized=event(oversized['state'],'inquiry');oversized=event(oversized['state'],'inquiry_check');oversized=event(oversized['state'],'inquiry_check_save',{'evidence':'1','method':'contains','expected':'ABSENT_FROM_PREFIX','requirement':'Missing content cannot be declared false from a prefix'});check('missing partial-output match stays unresolved',current(oversized)['checks'][-1]['verdict']=='Unresolved')
