result={'passed':passed,'scope':'Owner public-interface checks: controlled provider replies, native question records, finite comparisons, guarded file export and refinement transitions.'};(PROJECT/'output/checks/provider-evidence.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(dict(result,count=len(passed)),indent=2))
